  // progress modal sits on top, but the underlying page would otherwise
  // flash through (especially the dashboard on private routes, since
  // router.replace('/') is async).
  const isBootstrapping =
    status === 'idle' ||
    status === 'loading' ||
    status === 'creating_wallet' ||
    status === 'error';
