        <div className="relative z-[999] flex items-center justify-center min-h-screen p-4">
          {showInitialSdkLoading ? (
            <AuthLoadingState message="Loading…" />
          ) : isAwaitingOnboarding ||
            isBootstrapping ||
            isHandlingOAuthCallback ? null : (
            children
