        <div className="relative z-[999] flex min-h-screen items-center justify-center p-4 md:p-8 lg:p-12">
          {showInitialSdkLoading ||
          isBootstrapping ||
          isHandlingOAuthCallback ? (
            <AuthLoadingState message="Loading…" />
