                  <Header />
                  <main className="flex-1 backdrop-blur-sm rounded-lg">
                    {children}
                  </main>
                  <BuildInfo className="pb-8 text-center" />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      <AuthProgressModal />
    </div>
